 if(op==RSM_OP_CTU||op==RSM_OP_CTD)return tag_operand(a,tags,count,5u,false);
 if(op==RSM_OP_RES)return tag_operand(a,tags,count,4u,false)||tag_operand(a,tags,count,5u,false);
 if(op>=RSM_OP_EQ&&op<=RSM_OP_LE)return scalar_operand(a,tags,count,true)&&scalar_operand(b,tags,count,true);
