static state_t *state_for_slot(impl_t *m,uint32_t slot){uint32_t low=0u,high=m->states;while(low<high){uint32_t middle=low+(high-low)/2u,current=m->state[middle].slot;if(current<slot)low=middle+1u;else high=middle;}return low<m->states&&m->state[low].slot==slot?&m->state[low]:NULL;}
