rsm_status_t rsm_runtime_snapshot(const rsm_runtime_t*r,rsm_snapshot_writer_t*w){impl_t*m;uint32_t i;if(!r||!w||!w->value)return RSM_STATUS_INVALID_ARGUMENT;if(!r->impl)return RSM_STATUS_INVALID_STATE;m=r->impl;for(i=0;i<m->tags;i++){if(m->tag[i].type<=3){rsm_value_t logical,effective;logical.type=(rsm_data_type_t)m->tag[i].type;if(logical.type==RSM_TYPE_BOOL)logical.value.boolean=m->tag[i].v.b;else if(logical.type==RSM_TYPE_DINT)logical.value.dint=m->tag[i].v.d;else logical.value.real=m->tag[i].v.f;effective=logical;if(m->force[i].enabled)effective=m->force[i].value;if(w->value(w->context,i,&logical,&effective,m->force[i].enabled))return RSM_STATUS_HAL_ERROR;}else{uint8_t last=m->tag[i].type==4u?5u:9u,member;for(member=1u;member<=last;member++){rsm_value_t v;if(!member_ok(m->tag[i].type,member))continue;if(rsm_runtime_read_member(r,i,member,&v)||(w->member&&w->member(w->context,i,member,&v)))return RSM_STATUS_HAL_ERROR;}}}if(!m->states&&w->state&&w->state(w->context,(uint8_t)r->mode,&m->diag,&m->fault,UINT32_MAX,0u,0u,0u))return RSM_STATUS_HAL_ERROR;for(i=0;i<m->states;i++)if(w->state&&w->state(w->context,(uint8_t)r->mode,&m->diag,&m->fault,m->state[i].slot,m->state[i].edge,m->state[i].valid,m->state[i].time))return RSM_STATUS_HAL_ERROR;for(i=0;i<m->rungs;i++)if(w->rung_power&&w->rung_power(w->context,i,m->rung_power[i]))return RSM_STATUS_HAL_ERROR;return RSM_STATUS_OK;}
rsm_status_t rsm_runtime_snapshot_members(const rsm_runtime_t*r,rsm_snapshot_member_writer_t*w){if(!r||!w||!w->member)return RSM_STATUS_INVALID_ARGUMENT;/* compatibility API retains member-only traversal below. */{impl_t*m;uint32_t i;if(!r->impl)return RSM_STATUS_INVALID_STATE;m=r->impl;for(i=0;i<m->tags;i++){uint8_t last=m->tag[i].type==4u?5u:m->tag[i].type==5u?9u:0u,member;for(member=1u;member<=last;member++){rsm_value_t v;if(!member_ok(m->tag[i].type,member))continue;if(rsm_runtime_read_member(r,i,member,&v)||(w->member&&w->member(w->context,i,member,&v)))return RSM_STATUS_HAL_ERROR;}}}return RSM_STATUS_OK;}
rsm_status_t rsm_runtime_get_diagnostics(const rsm_runtime_t*r,rsm_runtime_diagnostics_t*d){if(!r||!d)return RSM_STATUS_INVALID_ARGUMENT;if(!r->impl)return RSM_STATUS_INVALID_STATE;*d=((impl_t*)r->impl)->diag;return RSM_STATUS_OK;}
const rsm_fault_t *rsm_runtime_last_fault(const rsm_runtime_t*r){return (r&&r->impl)?&((impl_t*)r->impl)->fault:NULL;}
